statechart.datamodel:
/* 1. Actor-local state and trusted ingress.
Each chart has its own isolated database. The helpers below run in that context; spawned adapters capture values in their goals.
context(Secret, Owner, RequestId) revision(Number, Scenario) pending(model|dispatch, Correlation) proposal(CanonicalFields) confirmation(Who, Revision, Fields) assessment(Decision) review_record(Who, Revision, Choice) outcome(Result)
demo_observer/1 is a test hook: notices go to that actor when installed, otherwise they are printed in the terminal. Use block comments throughout this datamodel: SXML normalizes whitespace in executable content. */
:- dynamic context/3, revision/2, pending/2, proposal/1, confirmation/3, assessment/1, review_record/3, outcome/1, demo_observer/1.
/* initialize(+Secret, +Scenario): start revision 1, owned by alice. */ initialize(Secret, Scenario) :- make_ref(Request), assertz(context(Secret, alice, Request)), assertz(revision(1, Scenario)), notify(started(1, Scenario)).
/* notify(+Event): publish an audit or application-outcome notice. */ notify(Event) :- ( demo_observer(Observer) -> self(Self), send(Observer, notice(Self, Event)) ; writeln(Event) ).
/* trusted(+Secret, +Principal, +Role): check a simulated wrapper envelope. The chart supplies Role (requester or reviewer). These identity comparisons do not authenticate a person; the terminal is privileged in this lab. */ trusted(Secret, Principal, Role) :- context(Key, Owner, _), Secret == Key, ( Role == requester -> Principal == Owner ; Principal == reviewer ).
current(Revision) :- revision(Current, _), Revision == Current.
/* 2. Asynchronous model simulation.
model_fixture(+Scenario, -Reply, -DelaySeconds) supplies scripted output. Scenario names replace free-text input in this editor example. Only the trusted adapter captures and attaches the key, correlation, and revision. The silent fixture sends nothing, allowing the chart's timer to expire. */ model_fixture(laptop, fields([service(laptop), cost(700)]), 0.1). model_fixture(vpn, fields([service(vpn), cost(10)]), 0.1). model_fixture(restricted, fields([service(restricted), cost(1)]), 0.1). model_fixture(missing, fields([service(laptop)]), 0.1). model_fixture(training, fields([service(training), cost(500)]), 0.1). model_fixture(invalid, fields([cost(-1)]), 0.1). model_fixture(model_error, error(unavailable), 0.1). model_fixture(slow, fields([service(restricted), cost(1)]), 2). model_fixture(silent, silent, 0). model_fixture(dispatch_failure, fields([service(laptop), cost(700)]), 0.1). model_fixture(dispatch_timeout, fields([service(laptop), cost(700)]), 0.1).
valid_scenario(Scenario) :- ground(Scenario), model_fixture(Scenario, _, _).
/* begin_model/0: store the fresh correlation before spawning a linked worker. Captured values remain those of this request even after a correction. */ begin_model :- context(Key, _, _), revision(Revision, Scenario), make_ref(Correlation), retractall(pending(_, _)), assertz(pending(model, Correlation)), self(Self), model_fixture(Scenario, Reply, Delay), notify(model_requested(Correlation, Revision, Scenario)), ( Reply == silent -> true ; spawn(( sleep(Delay), send(Self, model_result(Key, Correlation, Revision, Reply)) ), _, [link(true)]) ).
/* model_reply(+Secret, +Correlation, +Revision): admit the current operation. Identity checks reject stale values without binding an event into validity. */ model_reply(Secret, Correlation, Revision) :- context(Key, _, _), Secret == Key, current(Revision), pending(model, Expected), Correlation == Expected.
/* 3. Field validation and authoritative confirmation.
valid_fields(+Fields, -Canonical) accepts a ground list of at most two unique keys, then sorts it for display. Repeated identical fields and different values for the same key are both rejected. A valid partial list remains incomplete: schema validation alone does not permit dispatch. */ valid_fields(Fields, Canonical) :- ground(Fields), is_list(Fields), length(Fields, Count), Count =< 2, maplist(valid_field, Fields), sort(Fields, Canonical), length(Canonical, Count), findall(FieldName, (member(Field, Fields), functor(Field, FieldName, 1)), Keys), sort(Keys, Unique), length(Unique, Count).
valid_field(service(Service)) :- memberchk(Service, [laptop, vpn, restricted, training]). valid_field(cost(Cost)) :- integer(Cost), Cost >= 0, Cost =< 10000000.
remember(Fields) :- retractall(proposal(_)), assertz(proposal(Fields)).
show_summary :- revision(Revision, _), proposal(Fields), notify(summary(Revision, Fields)).
/* confirmed(+Secret, +Who, +Revision, +Fields): require the requester and exactly the displayed canonical snapshot at the current revision. */ confirmed(Secret, Who, Revision, Fields) :- trusted(Secret, Who, requester), current(Revision), proposal(Expected), Fields == Expected.
record_confirmation(Who, Revision, Fields) :- assertz(confirmation(Who, Revision, Fields)), notify(confirmed_by(Who, Revision, Fields)).
/* 4. Correction invalidates every decision made about the old revision. The active parent state accepts corrections before dispatch. Old linked workers may still reply; their obsolete envelopes cannot advance the chart. */ correct(Secret, Who, Revision, Scenario) :- trusted(Secret, Who, requester), current(Revision), valid_scenario(Scenario).
apply_correction(Scenario) :- retract(revision(Revision, _)), Next is Revision + 1, assertz(revision(Next, Scenario)), retractall(pending(_, _)), retractall(proposal(_)), retractall(confirmation(_, _, _)), retractall(assessment(_)), retractall(review_record(_, _, _)), notify(revised(Next)).
/* 5. Explicit sample policy and human review. The cuts in classify/2 define precedence: missing fields, conflict, prohibition, permission, then a policy gap. Prolog does not supply missing organisational knowledge or commonsense on behalf of these rules. */ complete(Fields) :- memberchk(service(_), Fields), memberchk(cost(_), Fields).
permit(Fields) :- memberchk(service(Service), Fields), memberchk(Service, [laptop, vpn]), memberchk(cost(Cost), Fields), Cost =< 1000.
forbid(Fields) :- memberchk(service(restricted), Fields). /* This legacy VPN rule deliberately conflicts with low-cost permission. */ forbid(Fields) :- memberchk(service(vpn), Fields).
classify(Fields, insufficient(missing_fields)) :- \+ complete(Fields), !. classify(Fields, conflicting) :- permit(Fields), forbid(Fields), !. classify(Fields, forbidden) :- forbid(Fields), !. classify(Fields, permitted) :- permit(Fields), !. classify(_, insufficient(policy_gap)).
assess :- proposal(Fields), revision(Revision, _), confirmation(_, Revision, Fields), classify(Fields, Decision), retractall(assessment(_)), assertz(assessment(Decision)), notify(assessed(Revision, Decision)).
decision(Decision) :- assessment(Decision).
show_review :- revision(Revision, _), proposal(Fields), assessment(Decision), notify(human_review(Revision, Fields, Decision)).
/* reviewed(+Secret, +Who, +Revision, +Fields, +Choice): the designated reviewer may reject, or approve a complete snapshot with a conflict or policy gap. Approval cannot fill missing fields or override a pure prohibition. */ reviewed(Secret, Who, Revision, Fields, Choice) :- trusted(Secret, Who, reviewer), current(Revision), proposal(Expected), Fields == Expected, memberchk(Choice, [approve, reject]), ( Choice == reject -> true ; complete(Fields), (assessment(conflicting); assessment(insufficient(policy_gap))) ).
record_review(Who, Revision, Choice) :- assertz(review_record(Who, Revision, Choice)), notify(reviewed_by(Who, Revision, Choice)).
/* 6. Asynchronous dispatch and terminal reporting.
begin_dispatch/0 rechecks confirmation and permission before dispatch. key(Request, Revision) identifies the confirmed operation; Correlation identifies this particular wait. The simulation implements no backend deduplication or durable storage. A missing acknowledgement leaves the external outcome unknown, even though the local workflow ends in failure. */ begin_dispatch :- revision(Revision, Scenario), proposal(Fields), confirmation(_, Revision, Fields), (assessment(permitted); review_record(reviewer, Revision, approve)), context(Key, Owner, Request), make_ref(Correlation), retractall(pending(_, _)), assertz(pending(dispatch, Correlation)), self(Self), notify(dispatch_requested(Correlation, Revision, key(Request, Revision), Owner, Fields)), ( Scenario == dispatch_timeout -> true ; ( Scenario == dispatch_failure -> Reply = error(refused) ; Reply = ok(ticket_42) ), spawn(( sleep(0.1), send(Self, dispatch_result(Key, Correlation, Revision, Reply)) ), _, [link(true)]) ).
dispatch_reply(Secret, Correlation, Revision) :- context(Key, _, _), Secret == Key, current(Revision), pending(dispatch, Expected), Correlation == Expected.
/* finish/1 records the application outcome; both final states call report/0. Normal actor termination alone does not establish application success. Linked workers stop with the chart; stopping cannot undo an external effect. */ finish(Result) :- retractall(outcome(_)), assertz(outcome(Result)).
report :- outcome(Result), revision(Revision, _), notify(terminal(Revision, Result)).
/* Discarding an event leaves the state active and does not reset its timer. */ ignored :- notify(ignored_event).
